javascript.solution:
const input = require("fs").readFileSync(0, "utf8");

function calculate(a, op, b) {
  switch (op) {
    case "+":
      return a + b;
    case "-":
      return a - b;
    case "*":
      return a * b;
    case "/":
      return Math.trunc(a / b);
    default:
      throw new Error(`unknown operator: ${op}`);
  }
}

const [left, op, right] = input.trim().split(/\s+/);
console.log(calculate(Number(left), op, Number(right)));

