#include <iostream>
#include <stdexcept>

int calculate(int a, char op, int b) {
    switch (op) {
        case '+':
            return a + b;
        case '-':
            return a - b;
        case '*':
            return a * b;
        case '/':
            return a / b;
        default:
            throw std::invalid_argument("unknown operator");
    }
}

int main() {
    int a, b;
    char op;
    std::cin >> a >> op >> b;
    std::cout << calculate(a, op, b) << "\n";
    return 0;
}

